import './style.css';
const $=id=>document.getElementById(id),canvas=$('town'),ctx=canvas.getContext('2d'),sheet=$('sheet'),content=$('sheet-content');
const storage={getItem(k){try{return localStorage.getItem(k)}catch{return null}},setItem(k,v){try{localStorage.setItem(k,v)}catch{}}};
let day=loadDay(storage),reads=loadReads(storage,stories.map(s=>s.id));
let mapData,segments=[],selected=places[0],car={x:-330,z:112,yaw:1.89,speed:0},spawn,route=[],auto=false,autoIndex=1,started=false,last=0,width=innerWidth,height=innerHeight,scale=1.1,google=null,street=null,tour=null,story=null,houseMode=false,currentPano=7,seenPano=null,timer,readyTimer,lastRoute=0;
let morning,schoolJourney=null,outing=loadOuting(storage),travelMode='drive',walkingSegments=[];
let afternoon=loadAfternoon(storage);
let missions=loadMissions(storage);
const saveMissions=()=>storage.setItem('ontario-missions-v1',JSON.stringify(missions));
const questProgress=()=>sideQuests.map(q=>sideProgress(q,day,missions));
function trackedQuest(){return questProgress().find(q=>q.id===missions.tracked&&!q.done);}
function followQuest(){const q=trackedQuest();if(q){select(places.find(p=>p.id===q.target));return true;}return false;}
function missionHud(){const q=trackedQuest();if(q){$('mission-title').textContent=q.title;$('mission-copy').textContent=q.steps.find(s=>!s.done).label+' · '+places.find(p=>p.id===q.target).name;$('outing-status').textContent='SIDE MISSION · '+q.title;$('resume-outing').textContent='Track side mission →';}}

const saveAfternoon=()=>storage.setItem('ontario-afternoon-v1',JSON.stringify(afternoon));
let houseEvent=loadOpenHouse(storage,outing),disposeHouseVideo=null;
const saveHouseEvent=()=>{storage.setItem('ontario-open-house-v1',JSON.stringify(houseEvent));refreshPropertyHud();};
const saveOuting=()=>storage.setItem('ontario-outing-v1',JSON.stringify(outing));
const keys=new Set(),pointers=new Map(),hold=k=>keys.has(k)||[...pointers.values()].includes(k),escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function say(text){$('toast').textContent=text;$('toast').classList.add('show');clearTimeout(timer);timer=setTimeout(()=>$('toast').classList.remove('show'),4200);}
function save(){storage.setItem('ontario-day-v1',JSON.stringify(day));$('count').textContent=day.done.length;}
function resetInput(){for(const id of pointers.keys())for(const b of document.querySelectorAll('[data-key]'))if(b.hasPointerCapture?.(id))b.releasePointerCapture(id);keys.clear();pointers.clear();document.querySelectorAll('.held').forEach(x=>x.classList.remove('held'));}
function setRoute(){route=routeBetween(travelMode==='walk'?walkingSegments:segments,[car.x,car.z],selected.parking);autoIndex=1;}
function select(p){selected=p;auto=false;setRoute();$('mission-title').textContent=day.done.includes(p.id)?'Another little detour.':p.id==='coffee'?'First, coffee.':p.id==='house'?'A house with a story.':p.type.toLowerCase().replace(/^./,c=>c.toUpperCase())+'.';$('mission-copy').textContent=`${p.name} · ${p.address}. Drive to the marker, slow down, and explore.`;refreshOuting();}
function disposeMedia(){disposeHouseVideo?.();disposeHouseVideo=null;clearTimeout(readyTimer);if(street){street.setVisible(false);google?.map.setStreetView(null);street=null;}if(tour){tour.disconnect();tour=null;}houseMode=false;}
function closeSheet(){if(morning?.isActive()){morning.skip();return;}disposeMedia();sheet.close();resetInput();}
$('close-sheet').onclick=closeSheet;sheet.addEventListener('cancel',e=>{e.preventDefault();closeSheet();});
function openSheet(tag,html){disposeMedia();auto=false;car.speed=0;resetInput();$('sheet-tag').textContent=tag;content.innerHTML=html;if(!sheet.open)sheet.showModal();sheet.scrollTop=0;}
function finish(p,i){const was=day.done.includes(p.id);day=complete(day,p.id,i);save();if(!was)say(`Inventory updated · ${p.reward}`);const q=questProgress().find(q=>q.id===missions.tracked);if(q?.done){missions={...missions,tracked:'main'};saveMissions();say('MISSION PASSED · '+q.reward);}else if(q)followQuest();}
function journal(tab='missions'){if(schoolJourney)return;openSheet('MISSIONS · YOUR UXBRIDGE DAY',missionMenu({tab,day,outing,afternoon,morning:loadMorning(storage),missions,places,travelMode,selected}));for(const b of content.querySelectorAll('[data-tab]'))b.onclick=()=>journal(b.dataset.tab);for(const b of content.querySelectorAll('[data-track]'))b.onclick=()=>{missions={...missions,tracked:b.dataset.track};saveMissions();closeSheet();if(!followQuest()){if(outing)resumeOuting();else morning.start(false);}say(b.dataset.track==='main'?'Family day tracked.':'Side mission tracked. Your family day progress is saved.');};for(const b of content.querySelectorAll('[data-dest]'))b.onclick=()=>{const p=places.find(p=>p.id===b.dataset.dest);closeSheet();auto=false;resetInput();Object.assign(car,{x:p.parking[0],z:p.parking[1],speed:0});select(p);say('Fast travel: '+p.name+'. Explore to play the activity.');};if($('ride'))$('ride').onclick=()=>{closeSheet();setRoute();auto=route.length>1;if(!auto)say('No connected route found. You can still move freely.');};}
$('journal-button').onclick=()=>journal();$('itinerary-button').onclick=()=>journal();
function stopMedia(p){if(p.id==='sundays')return `<figure class="slabtown-photo"><img src="${import.meta.env.BASE_URL}images/sundays.jpg" alt="Sundays restaurant window and a plated meal" width="1920" height="1280"><figcaption>SUNDAYS · 58 BROCK STREET WEST</figcaption></figure><p class="street-note"><b>A MICHELIN Guide restaurant, right here in Uxbridge.</b> Your local dinner plans have excellent credentials. <a href="${p.source}" target="_blank" rel="noopener">See Sundays in the MICHELIN Guide ↗</a></p>`;if(p.id==='books'||p.id==='bakery'){const book=p.id==='books';return `<figure class="slabtown-photo"><img src="${import.meta.env.BASE_URL}images/${book?'blue-heron-books':'little-thief-bakery'}.jpg" alt="${book?'Inside Blue Heron Books, with books and displays beside the counter':'Fresh pastries inside Little Thief Bakery'}" width="${book?348:1020}" height="${book?348:1020}"><figcaption>${book?'BLUE HERON BOOKS':'LITTLE THIEF BAKERY CO.'} · OWNER-SUPPLIED PHOTO</figcaption></figure>`;}if(p.id==='market')return `<figure class="slabtown-photo"><img src="${import.meta.env.BASE_URL}images/uxbridge-farmers-market.jpg" alt="Uxbridge Farmers’ Market stalls outside The Second Wedge brewery" width="1000" height="1000"><figcaption>UXBRIDGE FARMERS’ MARKET · OWNER-SUPPLIED PHOTO</figcaption></figure>`;if(p.id==='slabtown')return `<figure class="slabtown-photo"><img src="${import.meta.env.BASE_URL}images/slabtown-property.jpg" alt="Slabtown Cider property, patio and surrounding countryside" width="1920" height="1080"><figcaption>SLABTOWN CIDER CO. · 4559 CONCESSION ROAD 6</figcaption></figure><details class="menu-reference"><summary>See the supplied menu photo</summary><img src="${import.meta.env.BASE_URL}images/slabtown-menu.png" alt="Owner-supplied Slabtown menu used for the game’s cider choices" loading="lazy"></details>`;const view=streetViews[p.id];if(!view)return `<div class="stop-art"><small>${escape(p.type)}</small><span class="big-icon">${p.icon}</span><h3>${escape(p.name)}</h3><span class="fine">${p.id==='house'?'Step inside for the real iGUIDE tour':'Illustrated stop · real location'}</span>${p.id!=='house'?`<a class="primary" href="${streetLink(p)}" target="_blank" rel="noopener">Look around in Street View ↗</a><p class="fine">This stop’s embedded panorama is still being selected. Opens nearby available imagery in Google Maps.</p>`:''}</div>`;return `<div class="street-heading"><span class="eyebrow">LOOK AROUND · GOOGLE STREET VIEW</span><span class="fine">Hold and drag to look. Release to stop.</span></div><div class="street-viewer"><div class="street-toolbar"><button data-street-toggle>Done looking</button><button data-street-reset>Reset view</button></div><iframe class="street-embed" sandbox="allow-scripts allow-same-origin allow-forms allow-popups allow-popups-to-escape-sandbox allow-presentation allow-top-navigation-by-user-activation" title="Google Street View at ${escape(p.name)}" src="${escape(view.src)}" width="600" height="450" style="border:0" allowfullscreen loading="lazy" referrerpolicy="strict-origin-when-cross-origin"></iframe></div><div class="street-note">${escape(view.note)}${p.id==='dogwalk'?'<p><a class="primary" href="https://maps.app.goo.gl/kmmpgn4aN9ZKWsqS8" target="_blank" rel="noopener">Watch the Preserve nature video ↗</a></p><p class="fine">May 2023 video by Tina, hosted on Google Maps. Opens the exact shared clip.</p>':''}<div class="stop-links"><a href="${escape(view.openUrl)}" target="_blank" rel="noopener">Open this view in Google Maps ↗</a></div><p class="fine">If the view is unavailable, use the Google Maps link. You can still play the activity.</p></div>`;}
function stop(p){if(schoolJourney||!canVisit(car,p))return;if(outing?.next>=itinerary.length&&travelMode==='walk'&&afternoon.phase==='wander'){const before=afternoon.phase;afternoon=recordAfternoonVisit(afternoon,p.id);saveAfternoon();if(before!==afternoon.phase){if(!followQuest())select(places.find(q=>q.id==='house'));say('School pickup time! Head home for the car and sports bags.');}refreshOuting();}if(p.id==='house'&&houseEvent.active){openHouseStop(p);return;}const afterTask=outing?.next>=itinerary.length?afternoonTask(afternoon):null;if(afterTask&&(afterTask.id===p.id||(afterTask.phase==='pickup'&&p.id==='secondary'))){afternoonStop(p);return;}if(p.id==='slabtown'){slabtownStop(p);return;}if(outing&&(itinerary[outing.next]?.id===p.id||(outing.next===0&&p.id==='secondary'))){outingStop(p);return;}const done=day.done.includes(p.id);openSheet(p.type,`<div class="stop-layout"><div>${stopMedia(p)}</div><div class="stop-copy"><div class="address">${escape(p.address)}</div><h2>${escape(p.name)}</h2><div class="npc"><span class="portrait" aria-hidden="true">☺</span><div><b>Your inner small-town monologue</b><small>ORIGINAL FICTIONAL DIALOGUE</small></div></div><p>${escape(p.intro)}</p><p><b>${escape(p.prompt)}</b></p><div id="activity">${p.id==='house'?'<button id="enter-house" class="primary">Step inside the real house →</button>':done?`<div class="reply">${escape(p.replies[Number(day.choices[p.id])]||p.replies[0])}</div><p class="fine">✓ ${p.reward} · saved in your day journal</p><button id="back-road" class="primary">Back to the day →</button>`:p.choices.map((c,i)=>`<button class="choice" data-choice="${i}">${escape(c)}</button>`).join('')}</div><div class="stop-links"><a href="${p.source}" target="_blank" rel="noopener">Real place · learn more ↗</a></div></div></div>`);if(p.id==='meatmerchant'&&!hasSandwich(day)){$('activity').insertAdjacentHTML('beforeend','<button id="picnic-sandwich" class="choice">Collect sandwiches for the picnic →</button>');$('picnic-sandwich').onclick=()=>{finish(p,'sandwich');closeSheet();followQuest();say('Sandwiches in your inventory. Pastries next—or Elgin Park if you have them.');};}if(p.id==='elgin'){if(picnicReady(day,missions))$('activity').innerHTML='';$('activity').insertAdjacentHTML('beforeend',missions.picnic?'<div class="reply">✓ Picnic mission passed. Lunch enjoyed; memory saved in your inventory.</div>':picnicReady(day,missions)?'<button id="unpack-picnic" class="primary">Unpack pastries & sandwiches →</button>':'<p class="fine">Picnic side mission: collect Little Thief baked goods and Meat Merchant sandwiches, then unpack them here.</p>');if($('unpack-picnic'))$('unpack-picnic').onclick=()=>{missions=completePicnic(day,missions);saveMissions();finish(p,0);closeSheet();resumeOuting();say('MISSION PASSED · Picnic professional. Lunch enjoyed. Memory collected.');};}if($('enter-house'))$('enter-house').onclick=enterHouse;if($('back-road'))$('back-road').onclick=()=>{closeSheet();suggestNext(p);};for(const b of content.querySelectorAll('[data-choice]'))b.onclick=()=>{const i=Number(b.dataset.choice);finish(p,p.id==='meatmerchant'&&i===2?'sandwich':i);if(p.id==='slabtown'&&outing){outing={...outing,cider:true};saveOuting();refreshOuting();}$('activity').innerHTML=`<div class="reply">${escape(p.replies[i])}</div><p class="fine">✓ ${p.reward} · added to your day journal</p><button id="next-road" class="primary">Back to the day →</button>`;$('next-road').onclick=()=>{closeSheet();if(p.id==='slabtown'&&outing?.next===5)resumeOuting();else suggestNext(p);};};}

function afternoonStop(p){const task=afternoonTask(afternoon);if(!task)return;openSheet('AFTER SCHOOL · FAMILY LOGISTICS',`<div class="stop-layout"><div>${p.id==='house'?'<div class="stop-art"><small>55 BROCK STREET EAST</small><span class="big-icon">⌂</span><h3>The car is right where you left it.</h3></div>':stopMedia(p)}</div><div class="stop-copy"><span class="eyebrow">${escape(p.name)}</span><h2>${escape(task.title)}</h2><p>${escape(task.copy)}</p><div id="afternoon-activity">${task.phase==='pickleball'?'<div class="pickle-court"><div class="pickle-net"></div><div class="pickle-zone"></div><span class="pickle-ball"></span></div><p id="pickle-score">Return 3 balls. Tap when the ball is in the middle zone.</p><button id="pickle-return" class="primary">Return the ball!</button><button id="pickle-sidelines" class="small-link">Enjoy the sidelines instead →</button>':`<button id="afternoon-action" class="primary">${escape(task.action)} →</button>`}</div><p class="fine">Fictional family outing · simplified sports activity</p></div></div>`);const done=()=>{afternoon=advanceAfternoon(afternoon,task.id);saveAfternoon();if(task.phase==='car')Object.assign(car,spawn,{speed:0});if(['hockey','soccer','dinner'].includes(task.phase))finish(places.find(q=>q.id===task.id),task.phase==='dinner'?(day.choices.sundays??'dinner'):0);closeSheet();resumeOuting();say(task.reply);if(task.phase==='dinner')about(true);};if(task.phase!=='pickleball'){$('afternoon-action').onclick=done;return;}let points=0;const start=performance.now();$('pickle-return').onclick=()=>{const hit=matchMedia('(prefers-reduced-motion:reduce)').matches||rallyHit(((performance.now()-start)%1600)/1600);if(hit)points++;$('pickle-score').textContent=(hit?'Nice return! ':'Just wide—another ball is coming. ')+points+' / 3 returns';if(points>=3){$('afternoon-activity').innerHTML='<div class="reply">Pickleball comeback complete. Your youngest has finished soccer.</div><button id="finish-pickle" class="primary">Collect the youngest & head to the rink →</button>';$('finish-pickle').onclick=done;}};$('pickle-sidelines').onclick=done;}
function refreshPropertyHud(){$('property-status').textContent=houseEvent.active?'IN-GAME OPEN HOUSE · AGENT SHOWING YOUR HOME':houseEvent.watched?'OPEN HOUSE FINISHED · STILL FOR SALE':'YOUR HOME IS FOR SALE';}
function openHouseStop(p){openSheet('55 BROCK STREET EAST · YOUR OPEN HOUSE',`<div class="open-house-layout"><div class="movie-panel"><span class="eyebrow">YOUR AGENT IS SHOWING OFF THE HOUSE</span><iframe id="open-house-video" title="55 Brock Street East · open-house film" src="https://www.youtube-nocookie.com/embed/${HOUSE_VIDEO_ID}?enablejsapi=1&origin=${encodeURIComponent(location.origin)}&rel=0" allow="accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture; web-share" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe><p class="fine">Press Play. The in-game open house finishes when the film ends.</p></div><div class="stop-copy"><span class="eyebrow">YOU’RE SELLING YOUR HOME</span><h2>Let the house do the talking.</h2><p>Your real estate agent is welcoming visitors to 55 Brock Street East. That’s why you and the dog are out enjoying Uxbridge.</p><p>Here’s the home your agent is showing off. Settle in for the film while the last visitors look around.</p><a class="primary" href="${LISTING_URL}" target="_blank" rel="noopener">See the real house listing ↗</a><p class="fine">Fictional open-house story. See the actual listing for property details and viewing arrangements.</p><div id="open-house-result" role="status"></div><div id="open-house-fallback" class="hidden"><p class="fine">If the film won’t play here, watch it on YouTube, then confirm below.</p><a href="https://www.youtube.com/watch?v=${HOUSE_VIDEO_ID}" target="_blank" rel="noopener">Watch the film on YouTube ↗</a><button id="confirm-external-film" class="choice">I’ve watched the film on YouTube</button></div></div></div>`);const finishFilm=()=>{if(!houseEvent.active)return;houseEvent=endOpenHouse();saveHouseEvent();$('open-house-result').innerHTML='<div class="reply"><b>Open house finished. Welcome home.</b><p>Your agent wraps up. The dog can reclaim its favourite spot.</p></div><button id="after-open-house" class="primary">Continue your day →</button>';$('after-open-house').onclick=()=>{closeSheet();if(outing?.next===5)outingStop(p);};$('open-house-fallback').classList.add('hidden');say('Open house finished. 55 Brock Street East is ready for its next chapter.');};disposeHouseVideo=trackYoutube($('open-house-video'),state=>{if(houseAfterVideo(houseEvent,state)!==houseEvent)finishFilm();},()=>{$('open-house-fallback').classList.remove('hidden');});$('confirm-external-film').onclick=finishFilm;}
function slabtownStop(p){let selectedBottle=findCider(day.choices.slabtown);openSheet('SLABTOWN · PICK A BOTTLE FOR HOME',`<div class="stop-layout"><div>${stopMedia(p)}</div><div class="stop-copy"><span class="eyebrow">A PERFECTLY OPTIONAL DETOUR</span><h2>“Just one bottle.”</h2><p>Pick something for later. Your grocery run has developed a tasting-note vocabulary.</p><fieldset class="cider-menu"><legend>Choose your take-home bottle</legend>${ciders.map(c=>`<label class="cider-option" style="--cider-colour:${c.colour}"><input type="radio" name="cider" value="${c.id}" ${selectedBottle?.id===c.id?'checked':''}><span><b>${escape(c.name)}</b><small>${c.style} · ${c.abv}</small></span></label>`).join('')}</fieldset><div class="bottle-pick"><p id="cider-notes">${selectedBottle?escape(selectedBottle.notes):'Choose a cider to see its tasting notes.'}</p><button id="take-bottle" class="primary" ${selectedBottle?'':'disabled'}>Take this bottle home →</button><div id="bottle-reply" role="status"></div></div><button id="leave-cidery" class="small-link">${day.done.includes(p.id)?'Back to the day →':'Leave without a bottle →'}</button><p class="fine">Choices transcribed from your supplied menu photo. Fictional bottle pickup; this is not a live stock or price list.</p><a class="fine" href="${p.source}" target="_blank" rel="noopener">Visit Slabtown’s real website ↗</a></div></div>`);for(const input of content.querySelectorAll('input[name="cider"]'))input.onchange=()=>{selectedBottle=findCider(input.value);$('cider-notes').textContent=selectedBottle.notes;$('take-bottle').disabled=false;$('bottle-reply').textContent='';};$('take-bottle').onclick=()=>{if(!selectedBottle)return;finish(p,selectedBottle.id);if(outing){outing={...outing,cider:true};saveOuting();}$('bottle-reply').textContent=selectedBottle.name+' secured for home. You came out for groceries and acquired tasting notes.';$('take-bottle').textContent='✓ '+selectedBottle.name+' packed';$('take-bottle').disabled=true;$('leave-cidery').textContent='Back to the day →';say('In your bag: '+selectedBottle.name+' · for later.');};$('leave-cidery').onclick=()=>{closeSheet();if(outing?.next===5)resumeOuting();else suggestNext(p);};}
function suggestNext(p){if(followQuest())return;if(afternoonTask(afternoon)&&outing?.next>=itinerary.length){resumeOuting();return;}if(selected.id!==p.id||(outing&&outing.next<itinerary.length))return;const next=places.find(q=>['coffee','books','bakery','market','brewery','roxy','library','sundays','meatmerchant'].includes(q.id)&&!day.done.includes(q.id));if(next)select(next);say('Explore any nearby pin. The route is just a suggestion.');}
function normalise(p){return typeof p==='number'?p:Number(p?.id??p?.panoId??p?.position);}
function houseStory(){const room=rooms.find(r=>r.id===currentPano);story=stories.find(s=>s.roomIds.includes(room?.roomId))||stories.find(s=>s.id==='foyer');$('house-text').innerHTML=`<span class="eyebrow">${houseMode?'STORYBOOK MODE':escape(room?.room||'THE REAL HOUSE')} · ${reads.size} STORIES READ</span><h3>${escape(story.name)}</h3><p>${escape(story.body)}</p><p>${escape(story.reflection)}</p><p class="fine">${escape(story.detail)}</p><details class="sources"><summary>Historical sources & qualifications</summary>${story.sources.map(id=>{const s=sources.find(s=>s.id===id);return s?`<p>${s.url?`<a target="_blank" rel="noopener" href="${s.url}">${escape(s.title)} ↗</a>`:`<b>${escape(s.title)}</b> `}${escape(s.note)}</p>`:'';}).join('')}</details><div class="house-actions"><button id="read-room">${reads.has(story.id)?'✓ Read this story':'Save this room’s story'}</button><button id="next-story">${houseMode?'Next room story →':'Another room →'}</button><button id="storybook">${houseMode?'Return to panoramic tour':'Read stories without the viewer'}</button></div>${reads.size>=2?`<div class="reply"><b>House historian stamp collected.</b><p>You’ve stepped into two chapters of this real home. The house is also offered for sale—if this little day trip has you imagining a longer stay.</p><a href="https://www.realtor.ca/real-estate/30291114/55-brock-street-e-uxbridge" target="_blank" rel="noopener">See the actual house listing ↗</a></div><button id="house-back" class="primary">Back to the day →</button>`:''}`;$('read-room').onclick=()=>{reads.add(story.id);storage.setItem('ontario-house-reads',JSON.stringify([...reads]));if(reads.size>=2)finish(places.find(p=>p.id==='house'),'two-room-stories');houseStory();};$('next-story').onclick=()=>{const i=stories.indexOf(story),s=stories[(i+1)%stories.length],r=rooms.find(r=>s.roomIds.includes(r.roomId));if(!houseMode&&tour&&seenPano!==null){tour.tour.move(r.id,undefined,'crossfade');}else if(houseMode){currentPano=r.id;houseStory();}else{say('The tour is still connecting. You can switch to room stories.');}};$('storybook').onclick=()=>{houseMode=!houseMode;$('house-stage').classList.toggle('hidden',houseMode);if(!houseMode&&tour&&seenPano!==null)tour.tour.move(currentPano,undefined,'no-animation');houseStory();};if($('house-back'))$('house-back').onclick=closeSheet;}
function enterHouse(){openSheet('ONE STOP · A FEW CENTURIES OF STORIES',`<div class="house-stage" id="house-stage"><iframe id="house-frame" title="Real iGUIDE tour of Harrison House, 55 Brock Street East" src="https://youriguide.com/embed/lunnf_55_brock_st_e_uxbridge_on/?api=1&autostart=1&noinitanimation=1&nomenu&nogallery&nodetails&pano=7" allow="fullscreen" allowfullscreen></iframe><span class="house-status" id="house-status">Connecting to the real house…</span></div><div class="house-story"><div class="stop-links"><a href="https://youriguide.com/lunnf_55_brock_st_e_uxbridge_on/" target="_blank" rel="noopener">Open original tour ↗</a></div><div id="house-text"></div></div>`);currentPano=7;seenPano=null;houseMode=false;houseStory();const inst=new IGuideViewer($('house-frame'));tour=inst;readyTimer=setTimeout(()=>{if(tour===inst)$('house-status').textContent='Tour taking a while? Open the original tour, or read the room stories below.';},18000);inst.ready().then(()=>{if(tour!==inst)return;clearTimeout(readyTimer);seenPano=7;$('house-status').textContent='Real iGUIDE photography · tap floor markers to explore';inst.tour.floorplanResize('min');inst.addEventListener('tour:move-end',p=>{if(tour!==inst)return;const id=normalise(p);if(rooms.some(r=>r.id===id)){currentPano=id;seenPano=id;if(!houseMode)houseStory();}});}).catch(()=>{if(tour===inst)$('house-status').textContent='Viewer unavailable. Open the original tour or read the room stories below.';});}
function about(afterDinner=false){openSheet('ABOUT GREATER TORONTO AREA 55: UXBRIDGE',`<div class="notes">${afterDinner===true?'<div class="reply"><b>Family day: complete.</b><p>Dinner is done, but Uxbridge isn’t. Here’s the family behind this little adventure. There are still side quests and discoveries waiting.</p></div>':''}<h2>A family home. A new chapter.</h2><section class="family-story"><figure><img src="${import.meta.env.BASE_URL}images/family-trails.jpg" alt="Our family and dog together on the autumn trails near our Uxbridge home" width="1600" height="1067" loading="lazy"><figcaption>Us on the trails near our house, where my dog (and my parents) made plenty of friends.</figcaption></figure><p>I made this game to share a little of the life around our family home at 55 Brock Street East—and to help my parents find its next family.</p><p>My parents are downsizing. I live in Vancouver, and my sister lives in Kamloops. Now my parents are hoping to move to BC too, and we’re hoping to have the family all back together again soon.</p><p>Uxbridge has given us a lot to love, including the trails near our house. My dog made plenty of friends there. So did my parents. This little adventure is a way to share some of that everyday magic with whoever comes next.</p><h3>Why I made this</h3><p>I’m a software engineer who loves mixed media and believes AI can help improve our communities. This project brings those interests together: a way to advertise my parents’ house, and a video-game version of Uxbridge filled with personal touches and memories from my own life here.</p><p>I loved living in Uxbridge, especially all the nature around us. As a kid, I felt so free being able to walk to school, the movies, the candy store and all the little places that made the town feel like mine.</p><p>That’s the small-town feeling I wanted to capture in this game: the freedom to head out on foot, take a detour, find something familiar and make a day of it. By mixing the game with real photos, street views and the house tour, I wanted to share a little of what living here felt like—not just what the house looks like.</p><a class="primary" href="${LISTING_URL}" target="_blank" rel="noopener">Meet our family’s home · view the listing ↗</a><div class="continue-town"><h3>Your day doesn’t have to end here.</h3><p>Explore more of town, pick a side quest, or fast travel somewhere new. Your completed family missions are saved.</p><button id="continue-town" class="primary">Continue exploring & side quests →</button></div></section><h3>About the game</h3><p>An independent local exploration game. Real places, original fictional dialogue and imaginary purchases. No business, school, municipality, Google or iGUIDE endorsement is implied.</p><p>Explore any stops in any order. Collect three moments to finish a day, or wander through all the stops. One optional stop features a real historic home offered for sale. There are no real orders, tickets or reservations.</p><h3>Maps & photographs</h3><p>${google?'Google satellite imagery is connected.':'You are playing the illustrated map preview: real OpenStreetMap roads and building footprints, not satellite photography. Live Google satellite driving still needs the project owner’s API configuration.'} All seventeen town stops embed manually selected Google Street View panoramas without a developer key. Google serves the imagery directly; dates and coverage vary. The coffee shop and bookstore share a frontage panorama. Park/trail scenes show their roadside areas. iGUIDE supplies the real house photography from its original host. The drawings are illustrations, not storefront reconstructions. New stops use illustrated activities and source links; additional Street View panoramas have not yet been selected. The Countryside Preserve walk follows mapped OSM paths, with simplified game movement and a shortened return to the parked car. The optional Slabtown trip uses the expanded road map.</p><p>Some stop pins are approximate frontage positions, and game arrival markers are snapped to nearby mapped roads. School notes describe locations, not catchment eligibility. Elgin Park’s game arrival is not a verified vehicle entrance.</p><h3>Places & sources</h3><ul>${places.map(p=>`<li><a href="${p.source}" target="_blank" rel="noopener">${escape(p.name)}</a> · ${escape(p.address)}</li>`).join('')}</ul><p>Place references checked 22 October 2026. House history reuses the earlier project’s researched stories and qualifications, reviewed 21 October 2026. Your journal stays in this browser.</p><button id="restart-day" class="choice">Start a fresh journal (keep driving position)</button><button id="reset-whole-game" class="choice">Reset whole game →</button><p class="fine">Start over from the bedroom. Clears missions, inventory, house stories and all family-day progress on this browser.</p></div>`);$('continue-town').onclick=()=>journal('missions');$('reset-whole-game').onclick=confirmResetGame;$('restart-day').onclick=()=>{day={done:[],choices:{}};missions={tracked:'main',picnic:false};saveMissions();reads.clear();storage.setItem('ontario-house-reads','[]');save();closeSheet();say('Fresh notebook. Same lovely town.');};}
$('about').onclick=about;
function reset(){if(schoolJourney){say('The family is on the school walk. Finish it to return to the car.');return;}Object.assign(car,spawn,{speed:0});auto=false;resetInput();setRoute();say('Back on Brock Street. Your journal is safe.');}$('recenter').onclick=reset;
const mapping={KeyW:'north',ArrowUp:'north',KeyS:'south',ArrowDown:'south',KeyA:'west',ArrowLeft:'west',KeyD:'east',ArrowRight:'east'};
window.addEventListener('keydown',e=>{if(e.target instanceof HTMLInputElement||e.target instanceof HTMLTextAreaElement)return;if(sheet.open||$('welcome').open||schoolJourney)return;if(mapping[e.code]){e.preventDefault();keys.add(mapping[e.code]);auto=false;}if(!e.repeat){if(e.code==='KeyR')reset();if(e.code==='KeyE'){const nearby=nearbyPlaces(car,places);if(nearby.length)stop(nearby[0]);}}});window.addEventListener('keyup',e=>keys.delete(mapping[e.code]));window.addEventListener('blur',resetInput);document.addEventListener('visibilitychange',()=>{if(document.hidden)resetInput();});
for(const b of document.querySelectorAll('[data-key]')){b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);pointers.set(e.pointerId,b.dataset.key);b.classList.add('held');auto=false;};const up=e=>{pointers.delete(e.pointerId);if(![...pointers.values()].includes(b.dataset.key))b.classList.remove('held');};b.onpointerup=up;b.onpointercancel=up;b.onlostpointercapture=up;}
let touch=matchMedia('(pointer:coarse)').matches;function showTouch(){$('touch').classList.toggle('hidden',!touch);}showTouch();$('touch-toggle').onclick=()=>{touch=!touch;showTouch();};
function screen(p){if(schoolJourney){const b=schoolJourney.bounds,k=Math.min((width-70)/(b.maxX-b.minX+100),(height-360)/(b.maxZ-b.minZ+130));return [width/2+(p[0]-(b.minX+b.maxX)/2)*k,height/2-75+(p[1]-(b.minZ+b.maxZ)/2)*k];}return google?.screen(p)||[width/2+(p[0]-car.x)*scale,height/2+(p[1]-car.z)*scale];}
function resize(){width=innerWidth;height=innerHeight;const dpr=Math.min(devicePixelRatio||1,2);canvas.width=width*dpr;canvas.height=height*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);scale=width<700?1.25:1.55;}window.addEventListener('resize',resize);resize();
function poly(pts,fill,stroke,line=1){ctx.beginPath();pts.forEach((p,i)=>ctx[i?'lineTo':'moveTo'](...screen(p)));if(fill){ctx.closePath();ctx.fillStyle=fill;ctx.fill();}if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=line;ctx.stroke();}}
let clickPins=[];
function draw(){ctx.clearRect(0,0,width,height);ctx.save();if(google){ctx.beginPath();ctx.rect(0,0,width,height-65);ctx.clip();}if(!google){ctx.fillStyle='#d7dfba';ctx.fillRect(0,0,width,height);ctx.strokeStyle='#c5cfaa';ctx.lineWidth=1;for(let x=-1800;x<1800;x+=100)poly([[x,-1500],[x,1500]],null,'#c8d2ae');for(let z=-1500;z<1500;z+=100)poly([[-1800,z],[1800,z]],null,'#c8d2ae');for(const b of mapData.buildings){const q=screen(b.pts[0]);if(q[0]<-80||q[0]>width+80||q[1]<-80||q[1]>height+80)continue;poly(b.pts,'#c6c8a5','#b7bd9c');}for(const s of segments)poly([s.a,s.b],null,'#b5bc9b',(s.width+4)*scale);for(const s of segments)poly([s.a,s.b],null,'#f9f0d9',s.width*scale);}
for(const t of mapData.trails||[])poly(t.pts,null,'#85a276',2);
if(route.length&&!schoolJourney)poly(route,null,travelMode==='walk'?'#4d8568':google?'#f6aa50':'#dd8255',google?5:3.5);clickPins=[];const pins=schoolJourney?places.filter(p=>['house','secondary','elementary'].includes(p.id)):places.filter(p=>p.id!==selected.id).concat(selected);for(const p of pins){const q=screen(p.parking),sel=p.id===selected.id;if(q[0]<-30||q[0]>width+30||q[1]<-30||q[1]>height+30)continue;ctx.fillStyle=sel?'#d9673f':day.done.includes(p.id)?'#668665':'#294f43';ctx.beginPath();ctx.arc(q[0],q[1],sel?18:12,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#fff0ce';ctx.lineWidth=2;ctx.stroke();ctx.fillStyle='#fff1d7';ctx.font=`bold ${sel?14:11}px Arial`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(day.done.includes(p.id)?'✓':p.icon,q[0],q[1]);if(sel){ctx.font='bold 10px Arial';const tw=ctx.measureText(p.name).width;ctx.fillStyle='#203e37';ctx.fillRect(q[0]-tw/2-8,q[1]-43,tw+16,20);ctx.fillStyle='#fff1d7';ctx.fillText(p.name,q[0],q[1]-33);}clickPins.push({p,q});}

if(travelMode==='walk'){const q=screen([car.x,car.z]);ctx.fillStyle='#203e37';ctx.beginPath();ctx.arc(q[0],q[1],9,0,Math.PI*2);ctx.fill();ctx.fillStyle='#fff1d7';ctx.font='14px Arial';ctx.textAlign='center';ctx.fillText('●',q[0],q[1]);ctx.save();ctx.translate(q[0],q[1]);ctx.rotate(-car.yaw);ctx.fillStyle='#df794a';ctx.strokeStyle='#fff1d7';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(0,24);ctx.lineTo(-7,12);ctx.lineTo(7,12);ctx.closePath();ctx.fill();ctx.stroke();ctx.fillStyle='#fff1d7';ctx.beginPath();ctx.arc(0,-2,3,0,Math.PI*2);ctx.fill();ctx.fillRect(-3,2,6,5);ctx.restore();if(outing?.next===0){ctx.fillStyle='#d99062';ctx.beginPath();ctx.arc(q[0]-18,q[1]+8,5,0,Math.PI*2);ctx.fill();ctx.fillStyle='#527a9f';ctx.beginPath();ctx.arc(q[0]+18,q[1]+8,6,0,Math.PI*2);ctx.fill();}if(outing?.next<=1){const home=screen([spawn.x,spawn.z]);ctx.fillStyle='#dc784d';ctx.fillRect(home[0]-7,home[1]-13,14,26);ctx.fillStyle='#203e37';ctx.fillText('CAR + DOG · HOME',home[0],home[1]-20);}if(outing?.next===4){ctx.fillText('🐕',q[0]+19,q[1]+7);if(outing.hasToy){ctx.fillStyle='#e983a5';ctx.beginPath();ctx.arc(q[0]+33,q[1]+7,4,0,Math.PI*2);ctx.fill();}const parked=screen(places.find(p=>p.id==='trailparking').parking);ctx.fillStyle='#203e37';ctx.fillStyle='#dc784d';ctx.fillRect(parked[0]-7,parked[1]-13,14,26);ctx.fillStyle='#2e6257';ctx.fillRect(parked[0]-5,parked[1]-6,10,8);ctx.fillStyle='#203e37';ctx.fillText('P · CAR',parked[0],parked[1]-22);}}else{const q=screen([car.x,car.z]);ctx.save();ctx.translate(...q);ctx.rotate(-car.yaw);ctx.fillStyle='#203e3733';ctx.fillRect(-9,-15,22,38);ctx.fillStyle='#263c35';for(const x of [-10,7]){ctx.fillRect(x,-10,4,8);ctx.fillRect(x,8,4,8);}ctx.fillStyle='#dc784d';ctx.fillRect(-8,-18,16,36);ctx.fillStyle='#f3d5a2';ctx.fillRect(-6,-6,12,16);ctx.fillStyle='#2e6257';ctx.fillRect(-6,-9,12,5);ctx.fillRect(-6,10,12,5);ctx.fillStyle='#ffedbd';ctx.fillRect(-6,16,4,2);ctx.fillRect(2,16,4,2);ctx.restore();}
if(!google){ctx.fillStyle='#5e7864';ctx.font='10px Arial';ctx.textAlign='center';for(const name of ['Brock Street West','Brock Street East','Toronto Street South','Main Street North']){const s=segments.find(s=>s.name===name&&Math.hypot(...s.a)<550);if(s){const p=screen(s.a);ctx.fillText(name.toUpperCase(),p[0],p[1]+20);}}}ctx.textAlign='left';ctx.fillStyle=google?'#fff':'#45624e';ctx.font='bold 11px Arial';ctx.fillText('N ↑',width-45,115);ctx.restore();}
canvas.addEventListener('click',e=>{if(!started||sheet.open||schoolJourney)return;const found=[...clickPins].reverse().find(({q})=>Math.hypot(q[0]-e.clientX,q[1]-e.clientY)<23);if(found){if(canVisit(car,found.p))stop(found.p);else{select(found.p);say(`Destination: ${selected.name}`);}}});
$('visit').onclick=()=>{const nearby=nearbyPlaces(car,places);if(nearby.length)stop(nearby[0]);};
let nearbySignature='';
function refreshNearby(){const nearby=nearbyPlaces(car,places);$('arrival-prompt').classList.toggle('hidden',!nearby.length||sheet.open||!started||!!schoolJourney);$('arrival-label').textContent=nearby[0]?.name||'';const signature=nearby.map(p=>p.id).join(',');if(signature!==nearbySignature){nearbySignature=signature;$('nearby-stops').replaceChildren(...nearby.slice(1).map(p=>{const button=document.createElement('button');button.textContent='Explore '+p.name;button.onclick=()=>{stop(p);};return button;}));}}
function frame(now){requestAnimationFrame(frame);const dt=Math.min((now-last)/1000,.05)||.016;last=now;if(!mapData)return;if(started&&!sheet.open&&!$('welcome').open&&!schoolJourney){if(auto){let remaining=dt*(travelMode==='walk'?70:96);while(remaining>0&&autoIndex<route.length){const p=route[autoIndex],dx=p[0]-car.x,dz=p[1]-car.z,d=Math.hypot(dx,dz);if(d<remaining){car.x=p[0];car.z=p[1];remaining-=d;autoIndex++;}else{car.x+=dx/d*remaining;car.z+=dz/d*remaining;car.yaw=Math.atan2(dx,dz);remaining=0;}car.speed=travelMode==='walk'?70:96;}if(autoIndex>=route.length){auto=false;car.speed=0;say(`Arrived at ${selected.name}. Park & explore.`);}}else{for(let i=0;i<3;i++)compassStep(car,{north:hold('north'),south:hold('south'),west:hold('west'),east:hold('east')},dt/3,segments,travelMode==='walk');lastRoute+=dt;if(lastRoute>.8){setRoute();lastRoute=0;}}}
if(schoolJourney&&started&&!sheet.open&&!$('welcome').open){schoolJourney.time+=dt;updateSchoolJourney();}
if(google&&!schoolJourney){try{google.update(car);}catch{google=null;$('google-map').style.display='none';$('map-mode').textContent='ILLUSTRATED MAP PREVIEW · REAL OSM ROADS';$('osm-credit').classList.remove('hidden');}}draw();const near=nearest([car.x,car.z],segments);$('street').textContent=near.name.toUpperCase();const metres=remainingDistance([car.x,car.z],route,auto?autoIndex:1,selected.parking);const distanceLabel=metres>=1000?`${(metres/1000).toFixed(1)} km`:`${Math.round(metres)} m`;$('distance').textContent=distanceLabel;$('travel-distance').textContent=distanceLabel+' to '+selected.name;$('travel-time').textContent=travelEstimate(metres,travelMode);refreshNearby();$('vibe').textContent=travelMode==='walk'?'OLYMPIC ERRAND MODE':outing&&outing.next<itinerary.length?'THE FAMILY DAY':schoolJourney?'THE SCHOOL MORNING':auto?'RIDING THE SCENIC ROUTE':day.done.length>=3?'DAY WELL SPENT':`${day.done.length} / 3 GOOD MOMENTS`;}
function enterTown(){schoolJourney=null;document.body.classList.remove('school-journey');$('school-card').classList.add('hidden');$('google-map').style.visibility='';closeSheet();outing=null;saveOuting();travelMode='drive';Object.assign(car,spawn,{speed:0});document.body.classList.remove('on-foot');select(places[0]);refreshOuting();say('Free exploring. Replay morning to start the family day.');}
function beginSchoolJourney(){closeSheet();resetInput();missions={tracked:'main',picnic:false};saveMissions();afternoon={phase:'wander',visits:[]};saveAfternoon();houseEvent={active:false,watched:false};saveHouseEvent();outing={next:0,cider:false,version:3,hasToy:false};saveOuting();Object.assign(car,spawn,{speed:0});resumeOuting();say('School power-walk: both kids, one stop. The dog and car wait at home.');}
function refreshOuting(){const after=outing?.next>=itinerary.length?afternoonTask(afternoon):null;const task=after||(outing&&itinerary[outing.next]);$('outing-controls').classList.toggle('hidden',!outing);if(!outing){missionHud();return;}travelMode=outing.next>=itinerary.length?afternoonMode(afternoon):outingMode(outing);document.body.classList.toggle('on-foot',travelMode==='walk');$('outing-status').textContent=after?'AFTER SCHOOL · '+after.title:task?`${outing.next+1} / ${itinerary.length} · ${task.title}`:afternoon.phase==='done'?'FAMILY DINNER ✓ · DAY WELL SPENT':`POWER-WALK · ${Math.min(3,afternoon.visits.length)} / 3 DIFFERENT STOPS`;$('resume-outing').textContent=task?'Continue the day →':'Downtown discoveries →';$('optional-cider').classList.toggle('hidden',outing.next!==5||outing.cider);$('ride-outing').textContent=travelMode==='walk'?'Walk along →':'Ride along →';$('visit').textContent=travelMode==='walk'?'Explore · E':'Park & explore · E';$('recenter').textContent=travelMode==='walk'?'↺ Back home':'↺ Reset car';if(task&&selected.id===task.id){$('mission-title').textContent=task.title;$('mission-copy').textContent=task.copy;}else if(!task){$('mission-title').textContent=afternoon.phase==='done'?'Family dinner: accomplished.':'A wildly competitive power-walk.';$('mission-copy').textContent=afternoon.phase==='done'?'Dinner sorted. Wander some more, or visit the real house listing.':`Dog settled, car at home. Explore three different stops (${afternoon.visits.length}/3), then it’s school pickup. Next suggestion: ${selected.name}.`;}missionHud();}
function resumeOuting(){if(followQuest())return;if(!outing)return;travelMode=outing.next>=itinerary.length?afternoonMode(afternoon):outingMode(outing);select(places.find(p=>p.id===((outing.next>=itinerary.length?afternoonTask(afternoon)?.id:null)||itinerary[outing.next]?.id||'coffee')));refreshOuting();}
function outingStop(p){const original=itinerary[outing.next],task=original.id==='house'&&outing.next===5&&outing.cider?{...original,line:original.line+' '+ciderItem(day)+' is tucked away for later.'}:original.id==='dogwalk'?{...original,line:dogWalkLine(outing),reply:outing.hasToy?'Toy thoroughly tested. Dog delighted. Back to the car.':original.reply}:original;openSheet('YOUR FAMILY DAY · '+(outing.next+1)+' / '+itinerary.length,`<div class="stop-layout"><div>${p.id==='house'?'<div class="house-stage"><iframe title="Back home at 55 Brock Street East" src="https://youriguide.com/embed/lunnf_55_brock_st_e_uxbridge_on/?autostart=1&nomenu&nogallery&nodetails&pano=7" allow="fullscreen" allowfullscreen></iframe></div>':stopMedia(p)}</div><div class="stop-copy"><span class="eyebrow">${escape(p.name)}</span><h2>${escape(task.title)}</h2><p>${escape(task.line)}</p><p>${escape(task.copy)}</p>${p.id==='trailparking'?`<div class="toy-sidequest"><span class="eyebrow">OPTIONAL · WALMART NEXT DOOR</span><p id="toy-note">${outing.hasToy?'New toy in the bag. The dog is pretending to be casual.':'Pop over to Walmart for a dog toy before the walk—or head straight onto the trail.'}</p><button id="buy-toy" class="choice" ${outing.hasToy?'disabled':''}>${outing.hasToy?'✓ Dog toy collected':'Pick up a dog toy at Walmart'}</button><small>Fictional pickup · no real purchase</small></div>`:''}<button id="outing-action" class="primary">${escape(task.action)} →</button><div class="stop-links"><a href="${escape(p.source)}" target="_blank" rel="noopener">About this real place ↗</a></div><p class="fine">Original fictional family scene · imaginary purchases</p></div></div>`);if($('buy-toy'))$('buy-toy').onclick=()=>{outing=buyDogToy(outing);saveOuting();$('buy-toy').disabled=true;$('buy-toy').textContent='✓ Dog toy collected';$('toy-note').textContent='One squeaky toy secured. The dog has developed a sudden interest in shopping.';say('Optional pickup complete. New toy packed for the trail.');};$('outing-action').onclick=()=>{const previous=outing.next;outing=advanceOuting(outing,task.id);saveOuting();if(p.id!=='house')finish(p,0);if(previous===0){finish(places.find(q=>q.id==='elementary'),0);finish(places.find(q=>q.id==='secondary'),0);}closeSheet();if(previous===1){Object.assign(car,spawn,{speed:0});houseEvent=beginOpenHouse();saveHouseEvent();}if(previous===3){const parked=places.find(p=>p.id==='trailparking').parking;Object.assign(car,{x:parked[0],z:parked[1],speed:0});}if(previous===4){const parked=places.find(p=>p.id==='trailparking').parking;Object.assign(car,{x:parked[0],z:parked[1],speed:0});}if(outing.next===itinerary.length)Object.assign(car,spawn,{speed:0});resumeOuting();say(task.reply);if(previous===1)chooseDriveAudio();if(previous===4)offerDetour();};}
function chooseDriveAudio(){openSheet('DOG ABOARD · PICK YOUR SOUNDTRACK',`<div class="notes drive-audio-choice"><span class="eyebrow">NEXT STOP · VINCE’S MARKET</span><h2>Windows up. World out.</h2><p>The agent is showing the house. The dog has claimed the passenger seat. How are we driving?</p><button id="drive-with-radio" class="choice"><b>1 · Drive with the radio</b><span>Hits 105.5 · Uxbridge’s local station</span></button><button id="drive-in-silence" class="choice"><b>2 · Drive in silence</b><span>Just you, the dog, and the sound of absolutely no questions from the back seat.</span></button></div>`);$('drive-with-radio').onclick=()=>{closeSheet();if(!radioRequested){radioFailed=false;radioButton.click();}say('Hits 105.5 selected. Off to Vince’s with your co-pilot.');};$('drive-in-silence').onclick=()=>{closeSheet();stopRadio();canvas.focus({preventScroll:true});say('Quiet drive selected. The dog respects your need for a moment.');};}
function offerDetour(){openSheet('A PERFECTLY OPTIONAL DETOUR',`<div class="notes"><span class="eyebrow">GROCERIES ✓ · DOG WALK ✓</span><h2>“We’re already out…”</h2><p>Slabtown is a country-road detour to 4559 Concession Road 6. Pick up an imaginary bottle for later, or head straight home. Both continue the story.</p><button id="take-detour" class="primary">Detour to Slabtown →</button><button id="go-home" class="choice">Straight home with the dog →</button></div>`);$('take-detour').onclick=()=>{closeSheet();select(places.find(p=>p.id==='slabtown'));say('Optional mission: one bottle for home. No rush.');};$('go-home').onclick=()=>{closeSheet();resumeOuting();};}
$('resume-outing').onclick=()=>{if(followQuest())return;if(outing?.next>=itinerary.length&&!afternoonTask(afternoon)){journal();return;}resumeOuting();say('Your next chapter is marked on the map.');};
$('optional-cider').onclick=offerDetour;
$('skip-travel').onclick=()=>{if(sheet.open)return;auto=false;resetInput();Object.assign(car,{x:selected.parking[0],z:selected.parking[1],speed:0});setRoute();say('Travel shortened. You’ve arrived—explore to continue.');};
$('ride-outing').onclick=()=>{if(sheet.open)return;setRoute();auto=route.length>1;if(!auto)say('No connected route. You can still move freely or choose a nearby stop.');};
morning=createMorning({storage,rooms,openShell:openSheet,onDepart:beginSchoolJourney,onExplore:enterTown});
$('morning-replay').onclick=()=>{if(schoolJourney)enterTown();morning.start(true);};
async function boot(){$('welcome').showModal();try{const res=await fetch(`${import.meta.env.BASE_URL}data/uxbridge.json`);if(!res.ok)throw Error('Map unavailable');mapData=await res.json();segments=mapData.roads.flatMap(r=>r.pts.slice(1).map((b,i)=>({a:r.pts[i],b,width:r.kind==='service'?5:/primary|secondary|tertiary/.test(r.kind)?12:8,name:r.name})));walkingSegments=segments.concat((mapData.trails||[]).flatMap(t=>t.pts.slice(1).map((b,i)=>({a:t.pts[i],b,width:3,name:t.name}))));for(const p of places)p.parking=nearest(p.point,segments).q;const dog=places.find(p=>p.id==='dogwalk');const preserve=(mapData.trails||[]).filter(t=>t.name.includes('Countryside Preserve')).flatMap(t=>t.pts).filter(p=>Math.hypot(p[0]-dog.point[0],p[1]-dog.point[1])<250);if(preserve.length)dog.parking=preserve.reduce((a,b)=>Math.hypot(a[0]-dog.point[0],a[1]-dog.point[1])>Math.hypot(b[0]-dog.point[0],b[1]-dog.point[1])?a:b);places.find(p=>p.id==='trailparking').parking=project([-79.1317347,44.0876563]);const home=places.find(p=>p.id==='house'),n=nearest(home.parking,segments.filter(s=>s.name==='Brock Street East'));spawn={x:home.parking[0],z:home.parking[1],yaw:Math.atan2(n.b[0]-n.a[0],n.b[1]-n.a[1]),speed:0};Object.assign(car,spawn);select(selected);save();$('start').disabled=false;$('start').textContent=outing?'Continue your family day →':morning.isFinished()?'Replay the morning →':'Wake up at home →';$('start').onclick=()=>{$('welcome').close();started=true;resetInput();if(outing){Object.assign(car,spawn,{speed:0});if(outing.next===4){const parked=places.find(p=>p.id==='trailparking').parking;Object.assign(car,{x:parked[0],z:parked[1]});}resumeOuting();}else morning.start(morning.isFinished());};requestAnimationFrame(frame);const key=import.meta.env.VITE_GOOGLE_MAPS_API_KEY;if(key){const timeout=new Promise((_,reject)=>setTimeout(()=>reject(Error('Maps connection timed out')),12000));try{google=await Promise.race([googleScene($('google-map'),key),timeout]);$('map-mode').textContent='LIVE GOOGLE SATELLITE';$('osm-credit').classList.add('hidden');document.addEventListener('day-map-error',()=>{google=null;$('google-map').style.display='none';$('map-mode').textContent='ILLUSTRATED MAP PREVIEW · GOOGLE CONNECTION UNAVAILABLE';$('osm-credit').classList.remove('hidden');});}catch{say('Google imagery could not connect. The map preview is still playable.');}}}catch(e){$('start').textContent='Map unavailable — reload';$('start').disabled=false;$('start').onclick=()=>location.reload();console.error(e);}}
refreshPropertyHud();
boot();

canvas.tabIndex=0;
canvas.addEventListener('pointerdown',()=>canvas.focus({preventScroll:true}));
const radioButton=$('radio-button'),radioAudio=new Audio();
radioAudio.preload='none';
let radioRequested=false,radioFailed=false;
const radioStream='https://torres-media.streamb.live/SB00161?args=web_01&player_type=popup';
function radioLabel(text,playing=false){radioButton.textContent=text;radioButton.setAttribute('aria-pressed',String(playing));}
radioAudio.addEventListener('playing',()=>radioLabel('Ⅱ Hits 105.5 · Uxbridge',true));
radioAudio.addEventListener('waiting',()=>{if(radioRequested)radioLabel('… Hits 105.5 · Connecting',true);});
function radioError(){if(!radioRequested)return;radioRequested=false;radioFailed=true;radioLabel('↗ Hits 105.5 · Uxbridge');say('The station could not connect. Tap the radio button for its official player.');}
radioAudio.addEventListener('error',radioError);
function stopRadio(){radioRequested=false;radioAudio.pause();radioAudio.removeAttribute('src');radioAudio.load();radioLabel('▶ Hits 105.5 · Uxbridge');}
radioButton.onclick=async()=>{resetInput();canvas.focus({preventScroll:true});if(radioFailed){window.open('https://torres-media.streamb.online/CIUX-950928996/streamb-popup','_blank','noopener');radioFailed=false;radioLabel('▶ Hits 105.5 · Uxbridge');return;}if(radioRequested){stopRadio();return;}radioRequested=true;radioAudio.src=radioStream;radioLabel('… Hits 105.5 · Connecting',true);try{await radioAudio.play();}catch{if(radioRequested)radioError();}};
$('meditate').onclick=()=>{resetInput();auto=false;car.speed=0;const point=unproject([car.x,car.z]);const heading=(180-car.yaw*180/Math.PI+360)%360;window.open(`https://www.google.com/maps/@?api=1&map_action=pano&viewpoint=${point.lat},${point.lng}&heading=${heading}`,'_blank','noopener');say('Take a breath. Street View opens where you are; return here whenever you’re ready.');};

content.addEventListener('click',event=>{const control=event.target.closest('[data-street-toggle],[data-street-reset]');if(!control)return;const viewer=control.closest('.street-viewer'),frame=viewer.querySelector('iframe'),toggle=viewer.querySelector('[data-street-toggle]');resetInput();if(control.hasAttribute('data-street-reset')){frame.src=frame.src;viewer.classList.remove('view-frozen');toggle.textContent='Done looking';control.focus({preventScroll:true});return;}const frozen=viewer.classList.toggle('view-frozen');toggle.textContent=frozen?'Look around':'Done looking';if(document.pointerLockElement)document.exitPointerLock();toggle.focus({preventScroll:true});});

function confirmResetGame(){openSheet('START OVER',`<div class="notes"><h2>Start a brand-new day?</h2><p>This clears all missions, inventory, collected stops, house stories and family-day progress in this browser. You’ll return to the opening screen and wake up at home.</p><button id="confirm-reset-game" class="primary">Yes, reset the whole game</button><button id="cancel-reset-game" class="choice">Keep my progress</button></div>`);$('cancel-reset-game').onclick=about;$('confirm-reset-game').onclick=()=>{try{resetGame(localStorage);stopRadio();location.reload();}catch{say('Browser storage could not be cleared. Your game has not restarted.');}};}
